module team_selection (\n    input clk, rst_n, start,\n    input [3:0] n, p, s,\n    input [7:0] a [0:7],\n    input [7:0] b [0:7],\n    output reg [15:0] total,\n    output reg [7:0] prog_indices [0:7],\n    output reg [7:0] sports_indices [0:7],\n    output reg [3:0] prog_count,\n    output reg [3:0] sports_count,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] IDLE         = 4'd0;\n    localparam [3:0] COPY_INPUTS  = 4'd1;\n    localparam [3:0] SORT_A       = 4'd2;\n    localparam [3:0] STORE_PROG   = 4'd3;\n    localparam [3:0] INIT_SPORTS  = 4'd4;\n    localparam [3:0] SELECT_SPORT = 4'd5;\n    localparam [3:0] FIND_MAX     = 4'd6;\n    localparam [3:0] CALC_TOTAL   = 4'd7;\n    localparam [3:0] DONE_STATE   = 4'd8;\n\n    reg [3:0] state;\n    reg [7:0] temp_a [0:7];\n    reg [7:0] original_b [0:7];\n    reg [2:0] temp_indices [0:7];\n    reg [2:0] i, j, k;\n    reg [3:0] n_reg, p_reg, s_reg;\n    reg prog_flag [0:7];\n    reg selected [0:7];\n    reg [7:0] current_max;\n    reg [2:0] current_max_idx;\n    reg [3:0] sports_select_count;\n\n    integer idx;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            total <= 16'd0;\n            prog_count <= 4'd0;\n            sports_count <= 4'd0;\n            for (idx = 0; idx < 8; idx = idx + 1) begin\n                prog_indices[idx] <= 8'd0;\n                sports_indices[idx] <= 8'd0;\n                temp_a[idx] <= 8'd0;\n                original_b[idx] <= 8'd0;\n                temp_indices[idx] <= 3'd0;\n                prog_flag[idx] <= 1'b0;\n                selected[idx] <= 1'b0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        n_reg <= n;\n                        p_reg <= p;\n                        s_reg <= s;\n                        state <= COPY_INPUTS;\n                        k <= 0;\n                    end\n                end\n\n                COPY_INPUTS: begin\n                    temp_a[k] <= a[k];\n                    original_b[k] <= b[k];\n                    temp_indices[k] <= k[2:0];\n                    if (k == 3'd7) begin\n                        state <= SORT_A;\n                        i <= 3'd0;\n                        j <= 3'd0;\n                    end else begin\n                        k <= k + 1;\n                    end\n                end\n\n                SORT_A: begin\n                    if (i < n_reg && i < 3'd7) begin\n                        if (j < (n_reg - i - 4'd1)) begin\n                            if (temp_a[j] < temp_a[j+1]) begin\n                                // Swap a values\n                                temp_a[j] <= temp_a[j+1];\n                                temp_a[j+1] <= temp_a[j];\n                                // Swap indices\n                                temp_indices[j] <= temp_indices[j+1];\n                                temp_indices[j+1] <= temp_indices[j];\n                            end\n                            j <= j + 1;\n                        end else begin\n                            j <= 3'd0;\n                            i <= i + 1;\n                        end\n                    end else begin\n                        state <= STORE_PROG;\n                        k <= 0;\n                    end\n                end\n\n                STORE_PROG: begin\n                    if (k < p_reg) begin\n                        prog_indices[k] <= temp_indices[k];\n                        prog_flag[temp_indices[k]] <= 1'b1;\n                        k <= k + 1;\n                    end else begin\n                        prog_count <= p_reg;\n                        state <= INIT_SPORTS;\n                        k <= 0;\n                    end\n                end\n\n                INIT_SPORTS: begin\n                    sports_select_count <= 4'd0;\n                    for (idx = 0; idx < 8; idx = idx + 1) begin\n                        selected[idx] <= 1'b0;\n                    end\n                    state <= SELECT_SPORT;\n                end\n\n                SELECT_SPORT: begin\n                    if (sports_select_count < s_reg) begin\n                        current_max <= 8'd0;\n                        current_max_idx <= 3'd7;\n                        j <= 0;\n                        state <= FIND_MAX;\n                    end else begin\n                        sports_count <= sports_select_count;\n                        state <= CALC_TOTAL;\n                    end\n                end\n\n                FIND_MAX: begin\n                    if (j < n_reg) begin\n                        if (!prog_flag[j] && !selected[j] && (original_b[j] > current_max || (original_b[j] == current_max && j < current_max_idx))) begin\n                            current_max <= original_b[j];\n                            current_max_idx <= j[2:0];\n                        end\n                        j <= j + 1;\n                    end else begin\n                        if (current_max_idx < 3'd7) begin\n                            sports_indices[sports_select_count] <= current_max_idx;\n                            selected[current_max_idx] <= 1'b1;\n                            sports_select_count <= sports_select_count + 1;\n                        end\n                        state <= SELECT_SPORT;\n                    end\n                end\n\n                CALC_TOTAL: begin\n                    total <= 16'd0;\n                    for (k = 0; k < p_reg; k = k + 1) begin\n                        if (k < 8)\n                            total <= total + {8'd0, temp_a[k]};\n                    end\n                    for (k = 0; k < sports_select_count; k = k + 1) begin\n                        if (k < 8)\n                            total <= total + {8'd0, original_b[sports_indices[k]]};\n                    end\n                    state <= DONE_STATE;\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    // Stay in done until reset or new start\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule